// Part of the piezas CLI (see index.js).
//
// ===========================================================================
// Doctor PZ028 / PZ029 — the app uses real Piezas, not a homemade one
// ===========================================================================
//
// PZ028 (error): every @piezas/* dependency is the published package from npm
//   — no file:, link:, workspace:, git or tarball specs, no pre-releases, no
//   vendored copy (vendor/*piezas-sdk*.tgz, vendor/@piezas). A deploy pauses on
//   the same thing and the owner decides ("deploy anyway").
// PZ029 (warning): app code calls only Piezas addresses and SDK methods that
//   exist. Literal Piezas API addresses are checked against the API paths
//   snapshot (bundled from the Piezas MCP repo's reference/api-paths.json),
//   SDK method calls against the SDK exports snapshot; and direct HTTP to
//   Piezas is flagged where @piezas/sdk covers it.
import { readFileSync, readdirSync } from 'fs';
import { join } from 'path';
import { PIEZAS_API_REFERENCE, PIEZAS_SDK_REFERENCE } from './reference.js';
import { sdkProvenance } from './workspace.js';

// --- PZ028 -------------------------------------------------------------------

// A packed copy anywhere, vendor/@piezas, or anything in vendor/ named for
// Piezas (an unpacked vendor/piezas-sdk/ folder too), the same paths the
// workspace guard treats as Piezas's own package.
const VENDORED = /(?:^|\/)(?:[^/]*piezas-sdk[^/]*\.(?:tgz|tar\.gz|tar)|@piezas|vendor\/[^/]*piezas[^/]*)$/i;
const SKIP_DIRS = new Set(['node_modules', '.git', '.next', 'dist', 'build', 'out', '.piezas', 'coverage', '.turbo']);

// vendoredCopies — Piezas package copies kept in the project (depth 3).
export function vendoredCopies(projectDir) {
  const found = [];
  const walk = (dir, rel, depth) => {
    let entries;
    try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      const childRel = rel ? `${rel}/${e.name}` : e.name;
      if (VENDORED.test(childRel) && (e.isFile() || e.isDirectory())) { found.push(childRel); continue; }
      if (e.isDirectory() && !e.isSymbolicLink() && !SKIP_DIRS.has(e.name) && depth > 1) walk(join(dir, e.name), childRel, depth - 1);
    }
  };
  walk(projectDir, '', 3);
  return found.sort();
}

export function scanSdkProvenance(projectDir, findings, addFinding) {
  const verdict = sdkProvenance(projectDir);
  verdict.problems.forEach((p) => {
    if (p.where === 'unreadable') {
      addFinding(findings, 'error', 'PZ028', `${p.name} can't be read (not valid JSON), so which Piezas toolkit the app uses is unknown. ` +
        'Repair it (valid JSON: no comments or trailing commas) and reinstall.', p.file ?? p.name);
      return;
    }
    addFinding(
      findings,
      'error',
      'PZ028',
      `${p.name} ${p.problem}. Piezas apps use the published @piezas/sdk from npm, never a homemade or local copy — set a published ` +
        'version (`npm install @piezas/sdk@latest`) and reinstall. If the SDK lacks something the app needs, tell the owner ' +
        'in plain words what is missing and the options (contract Rule 11). A deploy pauses on this until the owner fixes it or ' +
        'says "deploy anyway".',
      p.where,
    );
  });
  for (const rel of vendoredCopies(projectDir)) {
    addFinding(
      findings,
      'error',
      'PZ028',
      `${rel} is a copy of a Piezas package kept in the app. Delete it and install the published @piezas/sdk from npm ` +
        '(contract Rule 11: do not build, pack or vendor Piezas\'s own code unless the owner explicitly asked for it after you ' +
        'explained the risk).',
      rel,
    );
  }
}

// --- PZ029 -------------------------------------------------------------------

const API_HOST = String.raw`https?:\/\/api(?:[.-]staging)?\.piezas\.ai`;
// A Piezas API address in code: a literal host, or a base read from a
// PIEZAS_*_URL setting, then a path.
const ADDRESS = new RegExp(
  String.raw`(?:(${API_HOST})|\$\{\s*(?:process\.env\.|env\.|config\(\)\.)?([A-Za-z_][A-Za-z0-9_.]*)\s*\})((?:\/(?:[A-Za-z0-9._~-]+|\$\{[^}]*\}))+)`,
  'g',
);
const HTTP_CALL = /\b(?:fetch|axios(?:\.[a-z]+)?|got|ky|request|undici\.request|http\.request|https\.request|superagent)\s*\(/;

function pathMatches(template, actual) {
  const t = template.split('/').filter(Boolean);
  const a = actual.split('/').filter(Boolean);
  if (t.length !== a.length) return false;
  return t.every((seg, i) => seg === a[i] || /^\{[^}]+\}$/.test(seg) || /^\$\{/.test(a[i]) || a[i] === ':param');
}

// knownPiezasPath — { service, known } for a path below the gateway
// (/<prefix>/v1/...) or below one service's base (/v1/... with service).
export function knownPiezasPath(path, service) {
  const ref = PIEZAS_API_REFERENCE;
  const services = ref.services || {};
  let svc = service;
  let rest = path;
  if (!svc) {
    const m = /^\/([^/]+)(\/.*)$/.exec(path);
    if (!m) return { service: null, known: false };
    svc = (ref.gatewayPrefixes || {})[m[1]] || (services[m[1]] ? m[1] : null);
    rest = m[2];
    if (!svc) return { service: m[1], known: false };
  }
  const paths = services[svc] || [];
  return { service: svc, known: paths.some((p) => pathMatches(p, rest)) };
}

// Which service a PIEZAS_<X>_URL setting points at (PIEZAS_API_URL: the gateway).
function serviceForSetting(name) {
  const m = /PIEZAS_([A-Z_]+?)_URL$/.exec(name.split('.').pop() || '');
  if (!m) return undefined;
  if (m[1] === 'API') return null;
  const key = m[1].toLowerCase().replace(/_/g, '-');
  const prefixes = PIEZAS_API_REFERENCE.gatewayPrefixes || {};
  return prefixes[key] || (PIEZAS_API_REFERENCE.services?.[key] ? key : undefined);
}

const NAMESPACE_CALL = /([A-Za-z_$][\w$]*(?:\(\))?(?:\.[A-Za-z_$][\w$]*)*)\.([a-z][A-Za-z0-9]*)\.([a-z][A-Za-z0-9]*)\s*(?:<[^>()]*>)?\s*\(/g;
// Built-in array/map/string methods never name an SDK call.
const BUILTIN_METHODS = new Set([
  'push', 'pop', 'shift', 'unshift', 'map', 'filter', 'find', 'findIndex', 'findLast', 'forEach', 'reduce', 'some', 'every',
  'includes', 'indexOf', 'slice', 'splice', 'sort', 'concat', 'join', 'flat', 'flatMap', 'at', 'reverse', 'fill', 'keys',
  'values', 'entries', 'get', 'set', 'has', 'delete', 'clear', 'add', 'toString', 'trim', 'split', 'replace', 'then', 'catch',
]);

const SDK_MODULE = String.raw`['"]@piezas\/sdk(?:\/[^'"]*)?['"]`;
// Any module whose path names piezas: '@/lib/piezas', './piezas', '../lib/piezas-client'.
const PIEZAS_PATH_MODULE = String.raw`['"][^'"\n]*[Pp][Ii][Ee][Zz][Aa][Ss][^'"\n]*['"]`;
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// piezasNames — the names in one file that stand for the Piezas SDK client:
// what it imports from @piezas/sdk (import / require), then, repeatedly,
// every variable, function or parameter made from one of those (const p = new
// Piezas(), const platform = () => p, function getClient() { return new
// Piezas() }, (client: Piezas) => ...). A name that cannot be traced to the
// SDK import is not the SDK: `const client = new Anthropic()` is someone else.
// With appModules, a name imported from the app's own module whose path names
// piezas (`import { client } from '@/lib/piezas'`) also counts as the client.
export function piezasNames(content, { appModules = false } = {}) {
  const names = new Set();
  const addBindings = (list) => {
    for (const part of String(list).split(',')) {
      const m = /(?:^|\s)(?:type\s+)?([A-Za-z_$][\w$]*)(?:\s+as\s+([A-Za-z_$][\w$]*))?\s*$/.exec(part.trim().replace(/:\s*([A-Za-z_$][\w$]*)$/, ' as $1'));
      if (m) names.add(m[2] ?? m[1]);
    }
  };
  const moduleRe = appModules ? PIEZAS_PATH_MODULE : SDK_MODULE;
  for (const m of content.matchAll(new RegExp(String.raw`import\s+([\w$\s,*{}]*?)\s+from\s+${moduleRe}`, 'g'))) {
    const clause = m[1];
    const braces = /\{([^}]*)\}/.exec(clause);
    if (braces) addBindings(braces[1]);
    const star = /\*\s+as\s+([A-Za-z_$][\w$]*)/.exec(clause);
    if (star) names.add(star[1]);
    const dflt = /^\s*(?:type\s+)?([A-Za-z_$][\w$]*)\s*(?:,|$)/.exec(clause);
    if (dflt && dflt[1] !== 'type') names.add(dflt[1]);
  }
  for (const m of content.matchAll(new RegExp(String.raw`(?:const|let|var)\s+(\{[^}]*\}|[A-Za-z_$][\w$]*)\s*=\s*(?:await\s+)?(?:import|require)\s*\(\s*${moduleRe}\s*\)`, 'g'))) {
    if (m[1].startsWith('{')) addBindings(m[1].slice(1, -1));
    else names.add(m[1]);
  }
  if (!names.size) return names;
  const mentions = (text) => [...names].some((n) => new RegExp(String.raw`(?:^|[^\w$.])${escapeRe(n)}(?![\w$])`).test(text));
  const declarations = [
    // const x = <expression> (to the end of the statement or line)
    ...[...content.matchAll(/(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*(?::[^=;\n]+)?=\s*([^;\n]*)/g)].map((m) => [m[1], m[2]]),
    // this.x = <expression>, x = <expression>
    ...[...content.matchAll(/(?:^|[\s;{(])(?:this\.)?([A-Za-z_$][\w$]*)\s*=(?![=>])\s*([^;\n]*)/g)].map((m) => [m[1], m[2]]),
    // function x(...) { ... } — its body up to the next top-level closing brace
    ...[...content.matchAll(/function\s*\*?\s+([A-Za-z_$][\w$]*)\s*\([^)]*\)[^{]*\{([\s\S]*?)\n\}/g)].map((m) => [m[1], m[2]]),
    // a parameter or field typed with an SDK type: (client: Piezas), piezas?: Piezas
    ...[...content.matchAll(/([A-Za-z_$][\w$]*)\??\s*:\s*([A-Za-z_$][\w$.]*)/g)].map((m) => [m[1], m[2]]),
  ];
  for (let changed = true; changed;) {
    changed = false;
    for (const [name, rhs] of declarations) {
      if (!names.has(name) && mentions(rhs)) {
        names.add(name);
        changed = true;
      }
    }
  }
  return names;
}

// rootOf — the name a receiver expression starts from: `platform()` ->
// platform, `this.piezas` -> piezas, `deps.piezas` -> deps.
function rootOf(receiver) {
  return receiver.replace(/^this\./, '').split(/[.(]/)[0];
}

export function scanUnknownAddresses(projectDir, files, findings, { addFinding, appSourceFiles, packageJson }) {
  const pkg = packageJson(projectDir) || {};
  const usesSdk = Object.keys({ ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) }).some((n) => n.startsWith('@piezas/'));
  const methods = new Set(PIEZAS_SDK_REFERENCE.methods || []);
  const namespaces = new Set([...methods].filter((m) => m.includes('.')).map((m) => m.split('.')[0]));
  const published = PIEZAS_SDK_REFERENCE.version ? ` ${PIEZAS_SDK_REFERENCE.version}` : '';
  const seen = new Set();
  for (const { filePath, rel } of appSourceFiles(projectDir, files)) {
    let content;
    try { content = readFileSync(filePath, 'utf-8'); } catch { continue; }
    const lineOf = (index) => content.slice(0, index).split('\n').length;
    for (const m of content.matchAll(ADDRESS)) {
      const [, host, setting, path] = m;
      let service;
      if (host) service = null;
      else {
        if (!/PIEZAS_[A-Z_]*URL$/.test(setting)) continue;
        service = serviceForSetting(setting);
        if (service === undefined) continue;
      }
      const verdict = knownPiezasPath(path.replace(/\?.*$/, ''), service);
      const shown = `${host || `\${${setting}}`}${path}`;
      const lineStart = content.lastIndexOf('\n', m.index) + 1;
      const lineEnd = content.indexOf('\n', m.index);
      const line = content.slice(lineStart, lineEnd < 0 ? content.length : lineEnd);
      const near = content.slice(Math.max(0, m.index - 200), m.index);
      const key = `${rel}:${shown}`;
      if (seen.has(key)) continue;
      seen.add(key);
      if (!verdict.known) {
        addFinding(findings, 'warn', 'PZ029',
          `${shown} is not a Piezas address: no such path in the Piezas API. Do not guess Piezas endpoints — use @piezas/sdk ` +
            'methods from the contract; if Piezas does not offer what the app needs, tell the owner (contract Rule 11).',
          rel, lineOf(m.index));
      } else if (HTTP_CALL.test(line) || HTTP_CALL.test(near.slice(-80))) {
        addFinding(findings, 'warn', 'PZ029',
          `${shown}: the app calls Piezas over HTTP directly. Use @piezas/sdk instead — it handles the key exchange, ` +
            'the app id and errors the way the contract expects.',
          rel, lineOf(m.index));
      }
    }
    if (!usesSdk || !methods.size) continue;
    const sdkNames = piezasNames(content);
    if (!sdkNames.size) continue;
    for (const m of content.matchAll(NAMESPACE_CALL)) {
      const [, receiver, ns, method] = m;
      if (!namespaces.has(ns) || BUILTIN_METHODS.has(method)) continue;
      if (!sdkNames.has(rootOf(receiver))) continue;
      const name = `${ns}.${method}`;
      if (methods.has(name)) continue;
      const key = `${rel}:${name}`;
      if (seen.has(key)) continue;
      seen.add(key);
      addFinding(findings, 'warn', 'PZ029',
        `${name}() is not part of the published @piezas/sdk${published}: it would call a Piezas address that does not exist. ` +
          'Use only SDK methods the contract names; if Piezas does not offer what the app needs, tell the owner (contract Rule 11).',
        rel, lineOf(m.index));
    }
  }
}
